-- Migration 017: exam tips that staff can edit from the admin panel.
-- One row per section; items is a JSON array of {"en": ..., "ar": ...}.
-- Seeded with the eight sections that used to be hard-coded in the candidate app.
-- No BEGIN/COMMIT here: scripts/migrate.ts wraps every file in one transaction.


CREATE TABLE IF NOT EXISTS tip_sections (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  position    int NOT NULL,
  title_en    text NOT NULL CHECK (length(title_en) BETWEEN 1 AND 200),
  title_ar    text NOT NULL CHECK (length(title_ar) BETWEEN 1 AND 200),
  items       jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(items) = 'array'),
  published   boolean NOT NULL DEFAULT true,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  uuid REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS tip_sections_position_idx ON tip_sections(position);

-- p_all = false: what candidates see (published only).
CREATE OR REPLACE FUNCTION tips_json(p_all boolean) RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', id, 'position', position, 'titleEn', title_en, 'titleAr', title_ar,
           'items', items, 'published', published, 'updatedAt', updated_at)
         ORDER BY position, id), '[]'::jsonb)
  FROM tip_sections WHERE p_all OR published;
$$;

-- Replaces every section in one transaction. The API validates the shape first.
CREATE OR REPLACE FUNCTION replace_tips(p_actor uuid, p_sections jsonb) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  v_before jsonb := tips_json(true);
BEGIN
  IF jsonb_typeof(p_sections) <> 'array' THEN RAISE EXCEPTION 'E_INVALID_TIPS'; END IF;
  DELETE FROM tip_sections;
  INSERT INTO tip_sections (position, title_en, title_ar, items, published, updated_by)
  SELECT s.ord::int, s.value->>'titleEn', s.value->>'titleAr', s.value->'items',
         coalesce((s.value->>'published')::boolean, true), p_actor
  FROM jsonb_array_elements(p_sections) WITH ORDINALITY AS s(value, ord);
  INSERT INTO audit_logs (actor_id, action, entity_type, entity_id, before, after)
  VALUES (p_actor, 'tips.replace', 'tips', 'exam-tips', v_before, tips_json(true));
END $$;

INSERT INTO tip_sections (position, title_en, title_ar, items)
SELECT * FROM (VALUES
  (1, $t$How the exam expects you to think$t$, $t$طريقة التفكير التي يتوقعها الامتحان$t$, $t$[{"en":"Answer as a project manager in a large, formal organization with a PMO and documented processes, not as things are done at your own company.","ar":"أجب كمدير مشروع في مؤسسة كبيرة ومنظمة لديها PMO وإجراءات موثقة، لا كما تجري الأمور في شركتك."},{"en":"Follow one order: assess, analyze, plan, then act. An answer that jumps to action before understanding the situation is rarely the best one.","ar":"اتبع ترتيبًا واحدًا: قيّم، حلّل، خطّط، ثم نفّذ. الإجابة التي تقفز إلى التنفيذ قبل فهم الموقف نادرًا تكون الأفضل."},{"en":"Talk to the people involved before you escalate. Going to the sponsor is a late step, not the first one.","ar":"تواصل مع أصحاب الشأن قبل التصعيد. الرجوع إلى الـ sponsor خطوة متأخرة وليست الأولى."},{"en":"You are a servant leader and an accountable leader: remove obstacles for the team, own your decisions, and do not pass problems upward.","ar":"أنت servant leader ومسؤول عن قراراتك: أزل العوائق عن الفريق، وتحمّل قرارك، ولا ترمِ المشكلة على من فوقك."},{"en":"Silence is not approval. If a stakeholder does not reply, follow up; do not assume agreement.","ar":"السكوت ليس موافقة. إذا لم يرد أحد أصحاب المصلحة فتابِع معه ولا تفترض أنه موافق."},{"en":"Safety and ethics are the exception to \"it depends\": follow safety rules and report unethical behavior, without negotiation.","ar":"السلامة والأخلاقيات هما الاستثناء من قاعدة «حسب الموقف»: التزم بقواعد السلامة وأبلغ عن أي سلوك غير أخلاقي دون تفاوض."}]$t$::jsonb),
  (2, $t$Reading the question$t$, $t$قراءة السؤال$t$, $t$[{"en":"Read the last sentence first, and read it twice. Words like FIRST, NEXT, BEST and EXCEPT change the answer.","ar":"اقرأ الجملة الأخيرة أولًا، واقرأها مرتين. كلمات مثل FIRST و NEXT و BEST و EXCEPT تغيّر الإجابة."},{"en":"Before looking at the options, decide: is this predictive, agile or hybrid? Which stage is the project in?","ar":"قبل النظر إلى الاختيارات حدّد: هل الموقف predictive أم agile أم hybrid؟ وفي أي مرحلة المشروع؟"},{"en":"\"What should the project manager do FIRST?\" usually means: understand the situation first. It does not mean: carry out the fix.","ar":"سؤال «ماذا يفعل مدير المشروع أولًا؟» يعني غالبًا: افهم الموقف أولًا، ولا يعني: نفّذ الحل."},{"en":"In a long case with several questions, read the questions first, then look in the text for what each one needs.","ar":"في دراسة الحالة الطويلة ذات الأسئلة المتعددة، اقرأ الأسئلة أولًا ثم ابحث في النص عمّا يحتاجه كل سؤال."},{"en":"Past tense (has happened, is now) describes an issue. \"Might\", \"could\" or \"may\" describes a risk. They are handled differently.","ar":"صيغة الماضي (حدث، أصبح) تصف issue. وكلمات مثل might و could و may تصف risk. ولكلٍّ منهما معالجة مختلفة."}]$t$::jsonb),
  (3, $t$Eliminating answers$t$, $t$استبعاد الإجابات$t$, $t$[{"en":"Most questions leave two reasonable options. Remove the two weak ones first and compare what is left.","ar":"أغلب الأسئلة يبقى فيها اختياران معقولان. استبعد الضعيفين أولًا ثم قارن بين الباقيَين."},{"en":"Be suspicious of absolute words: always, never, all, none, only, immediately. Project work depends on context, so these are usually wrong (safety and ethics aside).","ar":"احذر الكلمات المطلقة: always و never و all و none و only و immediately. إدارة المشاريع تعتمد على السياق، فهذه غالبًا خاطئة (عدا السلامة والأخلاقيات)."},{"en":"Remove options that escalate too early, and options where the project manager acts alone without analysis.","ar":"استبعد الاختيارات التي تصعّد مبكرًا، والتي يتصرف فيها مدير المشروع منفردًا دون تحليل."},{"en":"Between \"assess\" and \"act\", the assessment usually comes first.","ar":"بين «قيّم» و«نفّذ»، التقييم يأتي أولًا في الغالب."},{"en":"Prefer answers built on analysis, documentation, the agreed process and talking to stakeholders.","ar":"فضّل الإجابات المبنية على التحليل والتوثيق واتباع الإجراء المتفق عليه والتواصل مع أصحاب المصلحة."}]$t$::jsonb),
  (4, $t$Predictive or agile: the answer changes$t$, $t$Predictive أم Agile: الإجابة تتغير$t$, $t$[{"en":"Predictive scope change: a written change request, impact analysis, then the change control board. No shortcut for \"small\" changes, even when the sponsor asks.","ar":"تغيير النطاق في predictive: طلب تغيير مكتوب، ثم تحليل الأثر، ثم change control board. لا اختصار للتغييرات «الصغيرة» حتى لو طلبها الـ sponsor."},{"en":"Agile change: the product owner reorders the backlog for a later sprint. New work is not pushed into the sprint that is running.","ar":"التغيير في agile: الـ product owner يعيد ترتيب الـ backlog لـ sprint قادم. لا يُدخَل عمل جديد في الـ sprint الجاري."},{"en":"A verbal request is not a change. Ask for it in writing first, then analyze it.","ar":"الطلب الشفهي ليس تغييرًا. اطلب كتابته أولًا ثم حلّله."},{"en":"A story that does not meet the Definition of Done goes back to the backlog. It is not accepted \"almost done\".","ar":"الـ story التي لا تحقق Definition of Done تعود إلى الـ backlog، ولا تُقبل على أنها «شبه منتهية»."},{"en":"Definition of Done applies to every item; acceptance criteria belong to one story.","ar":"Definition of Done تنطبق على كل عنصر عمل، أما acceptance criteria فتخص story واحدة."}]$t$::jsonb),
  (5, $t$Rules that come up again and again$t$, $t$قواعد تتكرر كثيرًا$t$, $t$[{"en":"A new stakeholder appears: identify them, analyze their influence, update the engagement plan, then communicate. Do not ignore them and do not change the plan at once.","ar":"ظهور صاحب مصلحة جديد: عرّفه، حلّل تأثيره، حدّث خطة الـ engagement، ثم تواصل معه. لا تتجاهله ولا تغيّر الخطة فورًا."},{"en":"Conflict in the team: deal with it early, directly and in private, and aim for a solution both sides accept (collaborate). Use a firm decision only for emergencies and safety.","ar":"خلاف داخل الفريق: عالجه مبكرًا ومباشرة وعلى انفراد، واستهدف حلًا يقبله الطرفان (collaborate). القرار الحاسم للطوارئ والسلامة فقط."},{"en":"Check quality inside the team first, then ask the customer to accept the deliverable. A deliverable with known defects is not shown for acceptance.","ar":"افحص الجودة داخل الفريق أولًا، ثم اطلب من العميل قبول المخرَج. لا يُعرض للقبول مخرَج فيه عيوب معروفة."},{"en":"An identified risk is paid for from the contingency reserve. Something nobody foresaw needs the management reserve, and that needs approval.","ar":"الـ risk المحدَّد مسبقًا يُموَّل من contingency reserve. أما ما لم يتوقعه أحد فيحتاج management reserve، وهذا يحتاج موافقة."},{"en":"Residual risk is what remains after a response. Secondary risk is a new risk created by the response. Both are recorded.","ar":"Residual risk هو ما يبقى بعد الاستجابة. و secondary risk خطر جديد أنشأته الاستجابة. وكلاهما يُسجَّل."},{"en":"Plans change through change control; logs and registers are updated as part of daily work.","ar":"الخطط تتغير عبر change control، أما الـ logs والـ registers فتُحدَّث ضمن العمل اليومي."},{"en":"One change touches several things: a schedule change usually affects cost and resources too. An answer that updates only one of them is usually incomplete.","ar":"التغيير الواحد يمس أكثر من جانب: تغيير الجدول يؤثر غالبًا في التكلفة والموارد. الإجابة التي تحدّث جانبًا واحدًا فقط ناقصة في الغالب."},{"en":"With a supplier, the contract decides. Try negotiation before any formal dispute step.","ar":"مع المورّد، العقد هو الحكم. جرّب التفاوض قبل أي خطوة نزاع رسمية."},{"en":"Behind schedule with no extra money: fast-track. Money is available: crash. Both add risk.","ar":"تأخر في الجدول بلا ميزانية إضافية: fast-tracking. الميزانية متاحة: crashing. وكلاهما يزيد المخاطر."},{"en":"When the team lacks background, look at lessons learned and existing organizational knowledge before starting from nothing.","ar":"إذا افتقد الفريق الخلفية، ارجع إلى lessons learned والمعرفة الموجودة في المؤسسة قبل البدء من الصفر."},{"en":"If reports are being ignored, do not send more reports. Find out how the person prefers to communicate and switch to a conversation.","ar":"إذا كانت التقارير تُتجاهل فلا ترسل تقارير أكثر. اعرف الطريقة التي يفضّلها الشخص وانتقل إلى حوار مباشر."}]$t$::jsonb),
  (6, $t$Earned value and charts$t$, $t$Earned Value والرسوم$t$, $t$[{"en":"EV always comes first: SV = EV − PV, CV = EV − AC, SPI = EV ÷ PV, CPI = EV ÷ AC.","ar":"EV تأتي أولًا دائمًا: SV = EV − PV و CV = EV − AC و SPI = EV ÷ PV و CPI = EV ÷ AC."},{"en":"Compare before you calculate: EV above PV means ahead of schedule; EV above AC means under budget.","ar":"قارن قبل أن تحسب: EV أكبر من PV يعني تقدّمًا على الجدول، و EV أكبر من AC يعني أقل من الميزانية."},{"en":"For SPI and CPI, below 1.0 is bad. TCPI works the other way: above 1.0 means the remaining work must be done more efficiently than planned.","ar":"في SPI و CPI، أقل من 1.0 سيئ. أما TCPI فبالعكس: أكبر من 1.0 يعني أن العمل الباقي يحتاج كفاءة أعلى من المخطط."},{"en":"Forecasting order: CPI, then EAC = BAC ÷ CPI, then ETC = EAC − AC, then VAC = BAC − EAC.","ar":"ترتيب التوقع: CPI، ثم EAC = BAC ÷ CPI، ثم ETC = EAC − AC، ثم VAC = BAC − EAC."},{"en":"Burndown shows work remaining; burnup shows work completed and is the one that shows scope growing.","ar":"Burndown يعرض العمل المتبقي، و burnup يعرض العمل المنجز وهو الذي يُظهر زيادة النطاق."},{"en":"On a burndown chart, the actual line above the ideal line means the team is behind.","ar":"في burndown chart، خط الفعلي فوق الخط المثالي يعني أن الفريق متأخر."},{"en":"On a Kanban board, a column over its WIP limit is the bottleneck: the team helps clear it instead of starting new work.","ar":"في لوحة Kanban، العمود الذي تجاوز WIP limit هو الاختناق: الفريق يساعد في تصريفه بدل بدء عمل جديد."},{"en":"On any chart, find \"today\" first, then read the gap between the lines.","ar":"في أي رسم، حدّد «اليوم» أولًا ثم اقرأ الفرق بين الخطوط."}]$t$::jsonb),
  (7, $t$Time and test day$t$, $t$الوقت ويوم الامتحان$t$, $t$[{"en":"180 questions in 240 minutes is about 80 seconds a question. Check your pace at fixed points, not after every question.","ar":"180 سؤالًا في 240 دقيقة تعني نحو 80 ثانية للسؤال. راجع سرعتك عند نقاط ثابتة، لا بعد كل سؤال."},{"en":"Unsure? Choose your best answer, flag it and move on. Time lost early cannot be recovered at the end.","ar":"غير متأكد؟ اختر أفضل إجابة لديك، ضع علامة، وأكمل. الوقت الضائع في البداية لا يُعوَّض في النهاية."},{"en":"Take the breaks. Stand up, move and drink water; a rested mind answers better than a few saved minutes.","ar":"خذ الاستراحات. قف وتحرك واشرب ماء؛ الذهن المرتاح يجيب أفضل من دقائق قليلة توفّرها."},{"en":"Before the real exam, sit at least one full mock exam under real timing, then review every wrong answer and its explanation.","ar":"قبل الامتحان الحقيقي، أدِّ اختبارًا تجريبيًا كاملًا واحدًا على الأقل بالتوقيت الحقيقي، ثم راجع كل إجابة خاطئة وشرحها."},{"en":"Use one method for every question and apply it the same way each time. A steady method beats inspiration.","ar":"استخدم طريقة واحدة لكل سؤال وطبّقها بالشكل نفسه كل مرة. الطريقة الثابتة أفضل من الإلهام."}]$t$::jsonb),
  (8, $t$What is new in the July 2026 exam$t$, $t$الجديد في امتحان يوليو 2026$t$, $t$[{"en":"The 2026 outline gives the business environment more room: value delivery, governance, sustainability and the use of AI in projects. Expect scenarios on these, not only on scope, schedule and cost.","ar":"المخطط الجديد لعام 2026 يعطي بيئة الأعمال مساحة أكبر: تحقيق القيمة، والحوكمة، والاستدامة، واستخدام الـ AI في المشاريع. توقّع مواقف عن هذه الموضوعات، لا عن النطاق والجدول والتكلفة فقط."},{"en":"Ten of the 180 questions are unscored pretest items, and you cannot tell which ones. Treat every question as if it counts.","ar":"عشرة من الـ 180 سؤالًا تجريبية لا تُحتسب، ولا يمكنك معرفتها. تعامل مع كل سؤال كأنه محسوب."},{"en":"Case-study sets: several questions share one long scenario. PMI does not publish how many there are, so pace yourself with fixed checkpoints instead of guessing.","ar":"مجموعات دراسة الحالة: عدة أسئلة تشترك في موقف طويل واحد. PMI لا تعلن عددها، فنظّم وقتك بنقاط مراجعة ثابتة بدل التخمين."},{"en":"Graphic-based questions: read the title, axes, legend and units before the numbers. Most mistakes come from reading the chart too fast.","ar":"الأسئلة المبنية على رسوم: اقرأ العنوان والمحاور ومفتاح الرسم والوحدات قبل الأرقام. أغلب الأخطاء تأتي من قراءة الرسم بسرعة."},{"en":"Multiple-response questions tell you how many answers to pick. Judge each option on its own instead of looking for a matching pair.","ar":"أسئلة الاختيار المتعدد تحدد لك عدد الإجابات المطلوبة. احكم على كل اختيار وحده بدل البحث عن زوج متشابه."},{"en":"Drag-and-drop and matching: place the items you are sure of first. Each correct placement narrows the choices that are left.","ar":"أسئلة السحب والإفلات والمطابقة: ضع العناصر التي أنت متأكد منها أولًا. كل وضع صحيح يقلّل الاختيارات الباقية."},{"en":"AI in a project is a tool, not a decision maker: the project manager stays accountable, checks AI output, protects data and follows the organization's ethics and privacy rules.","ar":"الـ AI في المشروع أداة وليس صاحب قرار: مدير المشروع يبقى مسؤولًا، يراجع مخرجات الـ AI، ويحمي البيانات، ويلتزم بقواعد الأخلاقيات والخصوصية في المؤسسة."},{"en":"Value over output: prefer answers that link the work to business value, benefits and stakeholder outcomes, not only to finishing on time and on budget.","ar":"القيمة قبل المخرجات: فضّل الإجابات التي تربط العمل بقيمة الأعمال والفوائد ونتائج أصحاب المصلحة، لا بالانتهاء في الوقت والميزانية فقط."}]$t$::jsonb)
) AS seed(position, title_en, title_ar, items)
WHERE NOT EXISTS (SELECT 1 FROM tip_sections);

